        from fractions import Fraction

def verifier(assign):
    # Validate presence and types
    required = ['base_x', 'base_y', 'modulus', 'residue']
    for k in required:
        if k not in assign:
            # Missing slot
            return (False, None)
        if not isinstance(assign[k], int):
            return (False, None)
    a = assign['base_x']
    b = assign['base_y']
    m = assign['modulus']
    r = assign['residue']

    # Domain constraints
    if a < 2 or b < 2 or m < 2 or r < 0 or r >= m:
        return (False, None)

    # Compute area exactly via closed forms derived from geometric partition of (0,1]^2
    # Each k >= 0 corresponds to x in (a^{-(k+1)}, a^{-k}] of length (a-1)/a^{k+1}, similarly for l and b.
    # Condition: k + l ≡ r (mod m).
    try:
        A = Fraction((a - 1) * (b - 1), 1)
        if a != b:
            # General case: sum over t ≡ r mod m of sum_{k=0..t} A/(a^{k+1} b^{t-k+1})
            # Closed form: area = A/(b*(a-b)) * (S1 - S2),
            # where S1 = b^{-r} / (1 - b^{-m}), S2 = (b/a)^{r+1} b^{-r} / (1 - a^{-m}).
            q_a = Fraction(1, a)
            q_b = Fraction(1, b)
            S1 = q_b**r / (1 - q_b**m)
            S2 = (Fraction(b, a)**(r + 1)) * (q_b**r) / (1 - q_a**m)
            area = A * (S1 - S2) / Fraction(b * (a - b), 1)
        else:
            # Special case a == b: weights depend only on t = k + l, with multiplicity (t+1)
            # area = (a-1)^2/a^2 * sum_{n>=0} (r + 1 + m n) a^{-(r + m n)}
            # Let q = 1/a. Then sum_{n>=0} (r+1) q^{r + m n} + m n q^{r + m n}
            # = q^r [ (r+1) * 1/(1 - q^m) + m * (q^m)/(1 - q^m)^2 ]
            q = Fraction(1, a)
            common = q**r
            denom = (1 - q**m)
            geom = (r + 1) / denom
            arith_geom = Fraction(m, 1) * (q**m) / (denom**2)
            area = Fraction((a - 1) * (a - 1), a * a) * common * (Fraction(geom) + arith_geom)
        # Sanity: area in (0, 1)
        if area <= 0 or area >= 1:
            # Numerically extremely unlikely, but reject to be safe
            return (False, None)
        area = area.limit_denominator()  # ensure reduced fraction
        ans = area.numerator + area.denominator
        return True, int(ans)
    except Exception:
        return (False, None)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
